use Erikwang2013\IndustrialProtocols\Kernel;
use Erikwang2013\IndustrialProtocols\Modbus\ModbusProtocol;

$kernel = new Kernel(['config_path' => __DIR__ . '/industrial-protocols.php']);
$kernel->getProtocolRegistry()->register(new ModbusProtocol());
$kernel->boot();

$conn = $kernel->getConnectionManager()->connect('plc-001');
$result = $conn->read('40001');
echo $result['40001'];

use industrial_protocols_kernel::*;
use industrial_protocols_modbus::ModbusProtocol;

let mut kernel = Kernel::builder()
    .config_from_str(r#"
        [devices.plc-001]
        protocol = "modbus"
        variant = "tcp"
        host = "192.168.1.10"
        port = 502
        unit_id = 1
    "#)
    .with_protocol(Box::new(ModbusProtocol::tcp()))
    .build();

kernel.boot().expect("boot failed");
kernel.shutdown().expect("shutdown failed");
